export function EmptyState({
  headline = "{{headline}}",
  body = "{{body}}",
  icon = "{{icon}}",
  hasAction = {{hasAction}},
  actionLabel = "{{actionLabel}}",
}) {
  const glyph = { folder: "🗀", search: "🔍", inbox: "📥" }[icon] ?? "🗀";
  return (
    <div role="region" aria-label={headline} style={{ display: "flex", flexDirection: "column", alignItems: "center",
      textAlign: "center", gap: 6, maxWidth: 280, padding: "32px 20px", borderRadius: 12, border: "1.5px dashed #24143033",
      font: "14px/1.45 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ width: 44, height: 44, borderRadius: 12, background: "#D9C8F0",
        display: "grid", placeItems: "center", marginBottom: 8, fontSize: 20 }}>{glyph}</span>
      <p style={{ margin: 0, fontWeight: 700, fontSize: 15 }}>{headline}</p>
      <p style={{ margin: 0, color: "#24143099" }}>{body}</p>
      {hasAction && (
        <button type="button" style={{ marginTop: 10, border: "none", borderRadius: 8, background: "#241430",
          color: "#FAF7F2", fontWeight: 600, fontSize: 13, padding: "8px 16px", cursor: "pointer" }}>{actionLabel}</button>
      )}
    </div>
  );
}
